    TEST_ASSERT_EQUAL_STRING("2 0 min(calc(46% - 72px), calc(14% + 41px))", mb("min(calc(0.5 * (92% - 9rem)), calc((57% + 34vh) / 4))", 12000, 16000));
    TEST_ASSERT_EQUAL_STRING("1 600000 ", mb("37.5ch", 32000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 19%", mb("calc(77% * 0.25)", 24000, 16000));
    TEST_ASSERT_EQUAL_STRING("1 10000 ", mb("min(10px, 20px)", 16000, 20000));
    TEST_ASSERT_EQUAL_STRING("1 238500 ", mb("calc(49ch + 17ex)", 8000, 16000));
    TEST_ASSERT_EQUAL_STRING("2 0 calc(50% - 65px)", mb("calc(50% - 13ex)", 16000, 20000));
    TEST_ASSERT_EQUAL_STRING("2 0 max(60%, calc(162% - 480px))", mb("max(calc(40% * 1.5), calc(3 * (54% - 5em)))", 32000, 20000));
